output:
cat > magic.yara << 'EOF'
rule MagicBytes {
  condition:
    uint16(0) == 0x5A4D
}
EOF

cat > hash_rule.yara << 'EOF'
rule HashMatch {
  condition:
    hash.md5(0, filesize) == "d41d8cd98f00b204e9800998ecf8427e"
}
EOF

cat > position.yara << 'EOF'
rule PositionMatch {
  strings:
    $s = "marker"
  condition:
    @s < 0x1000
}
EOF

cat > external.yara << 'EOF'
rule ExternalCheck {
  condition:
    ext_var == 1
}
EOF

cat > math.yara << 'EOF'
rule MathCheck {
  condition:
    filesize % 1024 == 0
}
EOF
